// ── Math rendering (KaTeX) ──
// 显式声明定界符：auto-render 默认不含单 $，会导致 $N$ 这类行内公式原样显示。
function katexOptions() {
  return {
    delimiters: [
      { left: '$$', right: '$$', display: true },
      { left: '\\[', right: '\\]', display: true },
      { left: '\\(', right: '\\)', display: false },
      { left: '$', right: '$', display: false }
    ],
    throwOnError: false,
    ignoredTags: ['script', 'noscript', 'style', 'textarea', 'pre', 'code', 'option']
  };
}
function renderMathIn(el) {
  if (!el) return;
  if (!window.renderMathInElement) return;   // KaTeX 未加载（如离线）时静默跳过
  try { renderMathInElement(el, katexOptions()); } catch (e) { /* 单个公式错误不应打断整条消息 */ }
}

// ── Utilities ──
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// Simple markdown table → HTML
function parseTable(text) {
  const lines = text.trim().split('\n');
  if (lines.length < 2) return escapeHtml(text);
  const parseRow = (line) => line.split('|').slice(1, -1).map(c => c.trim());
  const headers = parseRow(lines[0]);
  const aligns = parseRow(lines[1]).map(c => c.startsWith(':') && c.endsWith(':') ? 'center' : c.endsWith(':') ? 'right' : 'left');
  const rows = lines.slice(2).map(parseRow).filter(r => r.length);
  const styleTh = (h, i) => `<th style="text-align:${aligns[i] || 'left'}">${h}</th>`;
  const styleTd = (c, i) => `<td style="text-align:${aligns[i] || 'left'}">${c}</td>`;
  const thead = `<thead><tr>${headers.map(styleTh).join('')}</tr></thead>`;
  const tbody = `<tbody>${rows.map(r => `<tr>${r.map(styleTd).join('')}</tr>`).join('')}</tbody>`;
  return `<table>${thead}${tbody}</table>`;
}

function md2html(text) {
  // Render markdown to HTML with LaTeX protection.
  // KaTeX handles \(...\) \[...\] $$...$$ after DOM insert.

  // Step 1: protect LaTeX blocks from markdown regexes
  const latexBlocks = [];
  let html = text;

  // protect display math: \[...\] and $$...$$
  html = html.replace(/\\\[([\s\S]*?)\\\]/g, (_, m) => {
    latexBlocks.push('\\[' + m + '\\]');
    return '\x00LATEXD' + (latexBlocks.length - 1) + '\x00';
  });
  html = html.replace(/\$\$([\s\S]*?)\$\$/g, (_, m) => {
    latexBlocks.push('$$' + m + '$$');
    return '\x00LATEXD' + (latexBlocks.length - 1) + '\x00';
  });
  // protect inline math: \(...\)
  html = html.replace(/\\\(([\s\S]*?)\\\)/g, (_, m) => {
    latexBlocks.push('\\(' + m + '\\)');
    return '\x00LATEXI' + (latexBlocks.length - 1) + '\x00';
  });
  // protect inline math: $...$（单美元；此时 $$ 已被摘走）
  // 启发式：内容不含中文，且（含 \ ^ _ = 等公式信号，或是短标识符），避免误吃 "$5 and $10"
  html = html.replace(/\$([^\$\n]{1,200})\$/g, (whole, m) => {
    if (/[\u4e00-\u9fa5]/.test(m)) return whole;
    const looksMath = /[\\^_=]/.test(m) || /^[A-Za-z][A-Za-z0-9]{0,3}$/.test(m);
    if (!looksMath) return whole;
    latexBlocks.push('$' + m + '$');
    return '\x00LATEXI' + (latexBlocks.length - 1) + '\x00';
  });

  // Step 1.5: protect Markdown tables (consecutive lines starting with |)
  const tableBlocks = [];
  html = html.replace(/(?:^\|.+\|\n?)+/gm, (m) => {
    tableBlocks.push(m.trim());
    return 'TBLID' + (tableBlocks.length - 1) + 'END\n';
  });

  // Step 2: escape HTML
  html = escapeHtml(html);

  // Restore table blocks → HTML tables
  html = html.replace(/TBLID(\d+)END/g, (_, i) => parseTable(tableBlocks[+i]));

  // Restore LaTeX placeholders — escape for HTML since they may contain & < >
  // 关键：公式内部换行必须压成空格；否则后面的段落步骤会插入 <br>，
  // 把 \[ 与公式体切成不同文本节点，KaTeX 的自动渲染就配不上定界符（只留字面 \[ \]）。
  const restoreMath = (i) => escapeHtml(String(latexBlocks[+i]).replace(/\s*\n\s*/g, ' '));
  html = html.replace(/\x00LATEXD(\d+)\x00/g, (_, i) => restoreMath(i));
  html = html.replace(/\x00LATEXI(\d+)\x00/g, (_, i) => restoreMath(i));

  // Step 3: markdown → HTML
  // fenced code blocks: ```...```
  html = html.replace(/```(\w*)\n([\s\S]*?)```/g, (_, lang, code) => {
    return `<pre><code>${code.trim()}</code></pre>`;
  });

  // inline code: `code`
  html = html.replace(/`([^`]+)`/g, '<code>$1</code>');

  // bold: **text**
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');

  // h3/h4: #### 必须先处理，否则会被 ### 规则吃掉一个 #
  html = html.replace(/^#### (.+)$/gm, '<h4>$1</h4>');
  html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');
  html = html.replace(/^## (.+)$/gm, '<h3>$1</h3>');

  // hr: --- (line start)
  html = html.replace(/^---$/gm, '<hr>');

  // blockquote: > text (line start)
  html = html.replace(/^&gt; (.+)$/gm, '<blockquote>$1</blockquote>');

  // unordered list: - item or * item (line start)
  html = html.replace(/^[-*] (.+)$/gm, '<li>$1</li>');

  // ordered list: 1. item
  html = html.replace(/^\d+\. (.+)$/gm, '<li>$1</li>');

  // wrap consecutive <li> in <ul>
  html = html.replace(/((?:<li>[^<]*<\/li>\n?)+)/g, '<ul>$1</ul>');

  // wrap consecutive <blockquote>
  html = html.replace(/((?:<blockquote>[^<]*<\/blockquote>\n?)+)/g, (m) => {
    const lines = m.replace(/<\/?blockquote>/g, '').trim().split('\n').filter(Boolean);
    return '<blockquote>' + lines.join('<br>') + '</blockquote>';
  });

  // paragraphs: split by \n\n
  const parts = html.split('\n\n');
  html = parts.map(p => {
    p = p.trim();
    if (!p) return '';
    if (p.startsWith('<h3>') || p.startsWith('<h4>') || p.startsWith('<pre>') ||
        p.startsWith('<ul>') || p.startsWith('<blockquote>') ||
        p.startsWith('<table') || p.startsWith('<hr')) return p;
    return '<p>' + p.replace(/\n/g, '<br>') + '</p>';
  }).join('\n');

  html = html.replace(/<p><\/p>/g, '');
  return html;
}

// ── Conversation Log Persistence ──
// 仅在本地起服务调试时把对话写到 /api/log；静态托管（GitHub Pages）没有该端点，
// 跳过可避免每个访问者的控制台刷 405。
const LOG_ENDPOINT_ENABLED = /^(localhost|127\.0\.0\.1)$/.test(location.hostname);

async function saveConversationLog(cardId, type, messages) {
  if (!LOG_ENDPOINT_ENABLED) return;
  const payload = {
    cardId: String(cardId),
    type: type,
    messages: messages.filter(m => m.role !== 'system')  // skip system prompt
  };
  try {
    await fetch('/api/log', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
  } catch {
    // silent fail — server might not be running
  }
}

function showToast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(t._timeout);
  t._timeout = setTimeout(() => t.classList.remove('show'), 2000);
}

// ── Keyboard Navigation ──
document.addEventListener('keydown', e => {
  // Prevent Space bar from scrolling the page when not typing in an input
  if (e.key === ' ' && !['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)) {
    e.preventDefault();
  }
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
    const cards = [...document.querySelectorAll('.card')];
    const nextInactive = cards.find(c => !c.classList.contains('active'));
    if (nextInactive) {
      nextInactive.classList.add('active');
      nextInactive.scrollIntoView({ behavior: 'smooth', block: 'start' });
      updateProgress();
      const cardId = nextInactive.dataset.card;
      Stats.onCard(activeLesson, cardId, true);
      if (!tabRendered[cardId]) { setTimeout(() => { renderQnA(cardId); tabRendered[cardId]=true; }, 0); }
    }
  }
});

// ── Auto-expand first card on load ──
(function() {
  const card1 = document.querySelector('.card[data-card="1"]');
  if (card1 && !card1.classList.contains('active')) {
    card1.classList.add('active');
    updateProgress();
    if (!tabRendered['1']) { setTimeout(() => { renderQnA('1'); tabRendered['1']=true; }, 0); }
  }
})();

