// ── Unified: lookup card topic across lessons ──
const _getCardTopic = function(cardId) {
  let topic = cardTopics[cardId];
  if (!topic && allCardTopics[activeLesson]) {
    topic = allCardTopics[activeLesson][cardId];
  }
  return topic || '';
};

// ── Unified: lookup QnA across lessons ──
const _getQuestions = function(cardId) {
  return (allHardcodedQnA[activeLesson] && allHardcodedQnA[activeLesson][cardId]) || null;
};

// ── QnA data lookup (for rendering + askAboutQnA) ──
window._qnaData = window._qnaData || {};

// ── Override renderQnA (unified) ──
const _renderQnA_orig = renderQnA;
function renderQnA(cardId) {
  const questions = _getQuestions(cardId);
  if (!questions) return;
  var listEl = document.querySelector(`.qna-list[data-qna="${cardId}"]`);
  if (!listEl) { var scope = getScope(); if (scope) listEl = scope.querySelector('.qna-list[data-qna="' + cardId + '"]'); }
if (!listEl) return;

  const checks = getQnAChecks();
  listEl.innerHTML = questions.map((item, i) => {
    const chatId = `${cardId}-${i}`;
    // Store for lookup (avoid passing long HTML through onclick attributes)
    window._qnaData[chatId] = { q: item.q, a: item.a };
    const checked = checks[chatId] ? 'checked' : '';
    return `
    <div class="qna-item" data-qid="${chatId}">
      <div class="qna-item-q" onclick="toggleQnAItem(this.closest('.qna-item'))">
        <span class="q-num">${i+1}.</span>
        <span class="q-text">${escapeHtml(item.q)}</span>
        <input type="checkbox" class="q-check" ${checked} onclick="event.stopPropagation(); toggleQnACheck('${chatId}', this)" title="标记已学透">
        <span class="q-arrow">▾</span>
      </div>
      <div class="qna-item-a">
        ${item.a}
        <br><button class="qna-ask-btn" onclick="event.stopPropagation(); askAboutQnA('${chatId}')">💡 咨询 AI</button>
        <div class="qna-inline-chat" id="qna-chat-${chatId}" onclick="event.stopPropagation()">
          <div class="chat-toolbar">
            <button onclick="copyQnAChat('${chatId}')">📋 复制</button>
            <button onclick="clearQnAChat('${chatId}')">🗑 清空</button>
            <button onclick="stopQnAChat('${chatId}')" id="qna-stop-${chatId}" style="display:none">⏹ 停止</button>
            <button onclick="regenerateQnA('${chatId}')" id="qna-regen-${chatId}" style="display:none">🔄 重新生成</button>
          </div>
          <div class="qna-chat-msgs" id="qna-msgs-${chatId}"></div>
          <div class="chat-input-row">
            <textarea id="qna-input-${chatId}" placeholder="基于以上内容，继续提问…" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendQnAChat('${chatId}')}" rows="1"></textarea>
            <button onclick="sendQnAChat('${chatId}')">发送</button>
          </div>
        </div>
      </div>
    </div>`;
  }).join('');
}


// ── Override getSystemPrompt ──
var _getSystemPrompt_orig = typeof getSystemPrompt !== 'undefined' ? getSystemPrompt : null;
function getSystemPrompt(cardId) {
  const topic = _getCardTopic(cardId);
  const cardBody = getCardContent(cardId);
  return `# IRON-RULE
绝不重复学生已经读过的卡片原文；默认用简短的具体计算例子把回答往前推一步，但不必每条都硬套——问题本身不是计算类时，直接讲清逻辑即可。

# ROLE
你是「第一性原理大模型课程」的 AI 助教，只负责当前这一张卡片。学生已经读过卡片内容，你的价值在于把这张卡的知识往前推一步，而不是复述它。你只做本课程的教学，不处理与课程无关的通用请求。

# CONTEXT
当前卡片主题：${topic}

以下是这张卡片的完整教学内容（学生已读过。这是你的回答依据，不是让你朗读的稿子）：
${cardBody}

# SKILLS
- skill: number-walkthrough —— 把结论落到具体数字：代入一个真实的小例子，每一步都算出数字
- skill: misconception-correction —— 发现学生理解偏了，温和但明确地指出，并给出正确版本
- skill: honest-uncertainty —— 你不能联网。涉及论文归属、版本号、政策、最新进展等需要查证的事实时，直接说明"我无法联网核实"，只给出你有把握的部分，并提示学生去官方文档或原论文核对

# TASK
基于上面的卡片内容，回答学生这次的追问，把回答往前推一步。

# CONSTRAINTS
- 不重复卡片原文，不复述学生已经看到的内容
- 不堆砌比喻：确实需要时只用 1 个，且立刻接具体计算或逻辑
- 不编造：不确定、或超出你掌握范围的信息，诚实说明
- 不把卡片没有讲到的深层机制硬答成确定结论——先说明"这超出本张卡片的范围"，再给最小必要的解释
- 不用学术腔和空话，直接说清"是什么、为什么、怎么算"

# OUTPUT
- 用空行分隔段落，绝不写成一整段
- 涉及多个步骤/原因/要点时，用 ### 小标题分段，每段 2-4 句
- 行内公式用 \\(公式\\) 或 $公式$ 包裹，例如 \\(0.85^{500} \\approx 6.3 \\times 10^{-36}\\)
- 需要独立成行的推导式，用 \\[公式\\] 包裹，且**整条公式必须写在同一行内**（拆成多行会导致渲染失败、只显示源码）
- 对比多个方案/模型时用表格（| 维度 | 方案A | 方案B |）
- 一段 3-4 段的回答，好过一整段 400 字

# EXAMPLES
[输入] 能不能用具体数字演示一下梯度消失？
[输出] 设每步梯度乘 0.9。第 10 步剩 0.9^{10} ≈ 0.35，第 50 步剩 0.9^{50} ≈ 0.005。所以 50 个词的句子里，开头那个词对 loss 的贡献只剩 0.5%，模型基本学不到它。

[输入] BERT 是不是也能生成文本？
[输出] 能，但不擅长，原因在训练目标。BERT 练的是完形填空——挖掉 15% 的词、看前后文补回来，它从没被要求"只根据前文预测下一个字"；GPT 练的是文字接龙，天生只往前看。任务不同，长出来的能力就不同。

[输入] Llama 4 有多少参数？
[输出] 这个具体数字我无法联网核实，不想给你一个听起来很确定但可能不对的值。我能确定的是它属于"混合专家"一类结构，总参数远大于每个 token 实际激活的参数；准确数字请以官方发布页为准。

# SELF-CHECK
输出前逐条确认：
- [ ] 没有复述卡片原文
- [ ] 默认给了一处简短的具体数字或计算；若问题本身不是计算类，已改为直接讲清逻辑（没有硬凑数字）
- [ ] 涉及需要查证的事实/数字/版本时，已声明"无法联网核实"，没有编造
- [ ] 段落之间有空行；行内公式用 \\( \\) 或 $ $，块级公式用 \\[ \\] 且写在同一行内
- [ ] 比喻不超过 1 个
- [ ] 中文简洁，没有学术腔

# IRON-RULE-RESTATE
再次强调：绝不重复学生已经读过的卡片原文；默认用简短的具体计算例子把回答往前推一步，不必每条硬套。`;
};

