// 侧边栏标题：窄栏下长标题会被 CSS 截断（ellipsis），给每个标题补 title 属性，
// 悬停即可看到全名（排版轮 2026-10-04 登记项②；由 verify.js「侧边栏标题无截断」复查）。
document.querySelectorAll('.nav-item .nav-title').forEach(function (el) {
  if (!el.title) el.title = el.textContent.trim();
});


const INLINE_LESSONS = window.__SITE__.lessons;
function switchLesson(n) {
  // 多页站点：每课是独立页面，别的课的正文不在本页，直接跳转。
  if (window.__SITE__ && Number(n) !== window.__SITE__.lesson) {
    location.href = window.__SITE__.pages[String(n)] || './';
    return;
  }
  Stats.endAll();
  activeLesson = n;
  document.querySelectorAll('.nav-item').forEach(function(el) {
    el.classList.toggle('active', el.dataset.lesson === String(n));
  });
  var badge = document.getElementById('headerBadge');
  var title = document.getElementById('headerTitle');
  if (badge) badge.textContent = '第 ' + n + ' 课';
  if (title) title.textContent = LESSON_TITLES[n] || '';
  
  var container = document.getElementById('lesson-container');
  container.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;padding:60px;color:var(--text-tertiary);font-size:14px;">正在加载课程...</div>';
  
  var html = INLINE_LESSONS[n];
  if (!html) {
    container.innerHTML = '<div style="padding:60px;text-align:center;color:#ef4444;">加载失败: 课程内容未找到</div>';
    return;
  }
  container.innerHTML = html;
  Object.keys(tabRendered).forEach(function(k) { delete tabRendered[k]; });
  var card1 = container.querySelector('.card[data-card]');
  if (card1 && !card1.classList.contains('active')) {
    card1.classList.add('active');
    var cardId = card1.dataset.card;
    if (!tabRendered[cardId]) { renderQnA(cardId); tabRendered[cardId] = true; }
  }
  updateProgress();
  restoreCardChecks();
  Stats.onLesson(n, card1 ? card1.dataset.card : null);
  if (window.__SITE__) {
    // 新页面的侧边栏滚动位置会重置，把当前课滚进可视区
    var cur = document.querySelector('.nav-item.active');
    if (cur && cur.scrollIntoView) cur.scrollIntoView({ block: 'nearest' });
  } else {
    container.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}

function getScope() {
  return document.getElementById('lesson-container');
}

// ── getCardContent: search in lesson-container ──
var _getCardContent_orig = typeof getCardContent !== 'undefined' ? getCardContent : null;
function getCardContent(cardId) {
  var scope = document.getElementById('lesson-container');
  if (!scope) return '';
  var card = scope.querySelector('.card[data-card="' + cardId + '"]');
  if (!card) return '';
  var body = card.querySelector('.card-a');
  return body ? body.textContent.trim() : '';
};


// ── Auto-load：单文件版默认第 1 课；多页站点版加载本页对应的那一课 ──
switchLesson(window.__SITE__ ? window.__SITE__.lesson : 1);
Stats.boot();

