    // 覆盖率闸门：先算出每篇候选文档对查询的覆盖率，再按「相对最佳候选」设下限。
    // 长的口语化查询里总有几个课程里没出现的字，不能要求每个词都命中；但也不能让只蹭到一个常见词的文档混进来。
    var cands = [], bestCov = 0;
    Object.keys(acc).forEach(function (id) {
      var cv = covered[id], got = 0;
      Object.keys(baseSet).forEach(function (b) { if (cv && cv[b]) got += baseMass[b]; });
      var cov = mass ? got / mass : 1;
      cands.push({ id: +id, cov: cov }); if (cov > bestCov) bestCov = cov;
    });
    var floor = MIN_COV; // 试过「相对最佳候选」的下限（0.6×best）：口语改写命中率没有任何提升，无关查询的噪声反而从平均 0.3 条涨到 4.0 条，已撤回
    var list = [], top = 0;
    cands.forEach(function (c) {
      if (c.cov < floor) return;
      var e = E.rows[c.id], s = acc[c.id] * (0.5 + 0.5 * c.cov);
      if (ex.cq.length >= 3 && compact(e.text).indexOf(ex.cq) !== -1) s *= 1.5;       // 整句命中主问题/课名
      else if (ex.cq.length >= 3 && compact(e.body).indexOf(ex.cq) !== -1) s *= 1.15;  // 整句命中正文
      if (!e.c) s *= 1.05;                                                              // 课程条目略微靠前
      list.push({ id: c.id, s: s }); if (s > top) top = s;
    });
